# MRR 计算
def mrr(queries, retrieved_docs, ground_truth):
    reciprocal_ranks = []
    for query in queries:
        for rank, doc in enumerate(retrieved_docs[query], 1):
            if doc == ground_truth[query]:
                reciprocal_ranks.append(1/rank)
                break
    return sum(reciprocal_ranks) / len(reciprocal_ranks)
